with g(rank,gloss) as (values (2,'Allah'),(8,'yang (laki-laki tunggal)'),(64,'mendustakan'),(67,'bertakwa'),(81,'hingga; sampai'),(84,'mengikuti'),(96,'menjadikan; mengambil'),(113,'surga; kebun'),(137,'pertama; awal'),(144,'berpaling'),(148,'Jahanam'),(167,'bukti yang nyata'),(185,'menyesatkan'),(186,'umat'),(195,'menurunkan (bertahap)'),(205,'keburukan; kejahatan'),(213,'menyentuh; menimpa'),(224,'tersesat'),(231,'Surga'),(234,'mengambil pelajaran; mengingat'),(240,'orang yang bertakwa'),(251,'menyangka'),(254,'memberitahukan'),(273,'bertasbih'),(281,'mengajarkan'),(285,'menyiksa'),(296,'bertawakal'),(303,'mengharamkan'),(306,'diberi kabar gembira'),(307,'yang mati'),(315,'menyelamatkan'),(320,'menghalangi')) update lemmas l set gloss_id=g.gloss from g where l.freq_rank=g.rank and l.gloss_id is null; update words w set gloss_id=l.gloss_id from lemmas l where w.lemma_id=l.id and w.gloss_id is null and l.gloss_id is not null;